-- =============================================================================
-- Satış + abonelik takip CRM — taşınabilir şema
-- Şartname: ../02-VERI-MODELI.md (alan gerekçeleri), ../03-IS-KURALLARI.md (davranış)
--
-- Söz dizimi MySQL 8. PostgreSQL için:
--   INT ... AUTO_INCREMENT      -> INTEGER GENERATED BY DEFAULT AS IDENTITY
--   TINYINT(1)                  -> BOOLEAN
--   DATETIME                    -> TIMESTAMP
--   ENGINE/CHARSET satırları    -> kaldır
--   INDEX tanımları             -> tablo dışında ayrı CREATE INDEX
-- Kendi projende migration aracı varsa onu kullan; bu dosya alan/indeks listesi olarak okunur.
--
-- Tablolar yeni ve additive; var olan şemaya dokunmaz. Önek: crm_
-- =============================================================================

-- -----------------------------------------------------------------------------
-- 1. Firma kartı
-- -----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS crm_account (
  account_id                  INT            NOT NULL AUTO_INCREMENT,
  name                        VARCHAR(200)   NOT NULL,                  -- adı bilinmiyorsa "İl — Kişi"
  stage                       VARCHAR(20)    NOT NULL DEFAULT 'new',
  stage_changed_at            DATETIME       NULL,
  owner_user_id               INT            NULL,                      -- sorumlu
  heat                        TINYINT        NULL,                      -- 1 soğuk · 2 ılık · 3 sıcak
  source                      VARCHAR(30)    NULL,                      -- cold|referral|inbound|event|other
  referral_note               VARCHAR(200)   NULL,
  lost_reason                 VARCHAR(30)    NULL,
  -- konum & profil
  city_id                     INT            NULL,
  district_id                 INT            NULL,
  branches                    VARCHAR(100)   NULL,                      -- virgüllü sözlük kodu
  organization_type           VARCHAR(20)    NULL,
  parent_account_id           INT            NULL,                      -- şube → üst kuruluş
  website_url                 VARCHAR(200)   NULL,
  instagram_url               VARCHAR(200)   NULL,
  facility_note               TEXT           NULL,
  tags                        VARCHAR(500)   NULL,                      -- virgüllü sabit sözlük
  -- rakip
  current_software            VARCHAR(120)   NULL,
  competitor_contract_ends_at DATE           NULL,                      -- yalnız ay biliniyorsa ayın 1'i
  competitor_annual_fee       DECIMAL(12,2)  NULL,
  competitor_note             VARCHAR(500)   NULL,
  -- sözleşme & ödeme (stage = member)
  company_id                  INT            NULL,                      -- ürün tarafındaki müşteri kaydı
  contract_type               VARCHAR(20)    NOT NULL DEFAULT 'paid',   -- paid|barter|gift|trial
  contract_starts_at          DATE           NULL,
  contract_ends_at            DATE           NULL,
  billing_period              VARCHAR(20)    NULL,                      -- monthly|quarterly|yearly|oneoff
  amount_incl_vat             DECIMAL(12,2)  NULL,                      -- KDV DAHİL; mesajda birebir yazılır
  currency                    VARCHAR(3)     NOT NULL DEFAULT 'TRY',
  next_due_date               DATE           NULL,                      -- vade
  payment_day_of_month        INT            NULL,                      -- 1-31; NULL = vade elle
  payment_reminder            INT            NOT NULL DEFAULT 0,        -- bu vade için otomatik mesaj gitti mi
  reminder_offset_days        INT            NULL,                      -- vade + N gün; NULL = 1
  auto_reminder_enabled       TINYINT(1)     NOT NULL DEFAULT 1,
  invoice_issued              TINYINT(1)     NOT NULL DEFAULT 0,        -- MEVCUT vadeye ait
  invoice_issued_at           DATETIME       NULL,
  invoice_no                  VARCHAR(50)    NULL,
  payment_note                VARCHAR(500)   NULL,                      -- ödeme kaydedilince taşınır ve temizlenir
  -- türetilmiş ama saklanan
  last_activity_at            DATETIME       NULL,                      -- aktivite eklemede güncellenir
  notes                       TEXT           NULL,
  import_key                  VARCHAR(100)   NULL,                      -- "<sayfa>:<satır>" — tekrar çalıştırılabilir içe aktarım
  needs_review                TINYINT(1)     NOT NULL DEFAULT 0,
  created_at                  DATETIME       NOT NULL,
  updated_at                  DATETIME       NULL,
  created_by_user_id          INT            NULL,
  is_deleted                  TINYINT(1)     NOT NULL DEFAULT 0,
  PRIMARY KEY (account_id),
  INDEX ix_acc_stage (stage),
  INDEX ix_acc_next_due (next_due_date),
  INDEX ix_acc_owner (owner_user_id),
  INDEX ix_acc_last_activity (last_activity_at),
  INDEX ix_acc_competitor_ends (competitor_contract_ends_at),
  INDEX ix_acc_company (company_id),
  UNIQUE INDEX ux_acc_import_key (import_key)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- -----------------------------------------------------------------------------
-- 2. Kişi (kişi + TEK numara; aynı kişide iki numara = iki satır)
-- -----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS crm_contact (
  contact_id                INT            NOT NULL AUTO_INCREMENT,
  account_id                INT            NOT NULL,
  name                      VARCHAR(150)   NULL,                        -- bilinmiyorsa NULL + note
  role                      VARCHAR(30)    NULL,
  is_decision_maker         TINYINT(1)     NOT NULL DEFAULT 0,
  is_primary                TINYINT(1)     NOT NULL DEFAULT 0,          -- firma başına en çok bir
  phone_raw                 VARCHAR(30)    NULL,                        -- girildiği gibi; ASLA atılmaz
  phone_e164                VARCHAR(20)    NULL,                        -- normalize (ör. 905xxxxxxxxx)
  is_whatsapp               TINYINT(1)     NOT NULL DEFAULT 1,
  receives_payment_reminder TINYINT(1)     NOT NULL DEFAULT 0,          -- is_primary'den BAĞIMSIZ
  email                     VARCHAR(200)   NULL,
  note                      VARCHAR(300)   NULL,
  sort_order                INT            NOT NULL DEFAULT 0,
  import_key                VARCHAR(120)   NULL,
  created_at                DATETIME       NOT NULL,
  updated_at                DATETIME       NULL,
  is_deleted                TINYINT(1)     NOT NULL DEFAULT 0,
  PRIMARY KEY (contact_id),
  INDEX ix_cnt_account (account_id),
  INDEX ix_cnt_phone (phone_e164),                                      -- TEKİL DEĞİL: mükerrer uyarısı için
  UNIQUE INDEX ux_cnt_import_key (import_key)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- -----------------------------------------------------------------------------
-- 3. Aktivite — temas günlüğü (GEÇMİŞ)
-- -----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS crm_activity (
  activity_id        INT            NOT NULL AUTO_INCREMENT,
  account_id         INT            NOT NULL,
  contact_id         INT            NULL,
  activity_type      VARCHAR(20)    NOT NULL,                           -- call|whatsapp|email|demo|visit|offer|note
  direction          VARCHAR(10)    NULL,                               -- outbound|inbound
  outcome            VARCHAR(30)    NULL,
  occurred_at        DATETIME       NULL,                               -- NULL yalnız içe aktarımda
  summary            TEXT           NOT NULL,                           -- uzun: 1.300+ karakter görülüyor
  materials          VARCHAR(100)   NULL,                               -- video,screenshots,links,mail,offer
  offer_amount       DECIMAL(12,2)  NULL,
  offer_note         VARCHAR(300)   NULL,
  created_by_user_id INT            NOT NULL,                           -- görüşen kişi
  import_key         VARCHAR(120)   NULL,
  created_at         DATETIME       NOT NULL,
  updated_at         DATETIME       NULL,
  is_deleted         TINYINT(1)     NOT NULL DEFAULT 0,
  PRIMARY KEY (activity_id),
  INDEX ix_act_account_occurred (account_id, occurred_at),
  UNIQUE INDEX ux_act_import_key (import_key)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- -----------------------------------------------------------------------------
-- 4. Görev (GELECEK) — ajanda / e-posta / push / takvim tek kaynağı
-- -----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS crm_task (
  task_id            INT            NOT NULL AUTO_INCREMENT,
  account_id         INT            NOT NULL,
  contact_id         INT            NULL,
  task_type          VARCHAR(20)    NOT NULL,                           -- call|whatsapp|email|demo|visit|other
  due_date           DATE           NOT NULL,                           -- HER ZAMAN somut
  due_time           TIME           NULL,                               -- NULL = tüm gün
  due_is_approx      TINYINT(1)     NOT NULL DEFAULT 0,                 -- arayüzde "~"
  due_label          VARCHAR(60)    NULL,                               -- "bayramdan sonra"
  priority           VARCHAR(10)    NOT NULL DEFAULT 'normal',          -- normal|must
  note               VARCHAR(500)   NULL,                               -- arama ÖNCESİ not
  status             VARCHAR(10)    NOT NULL DEFAULT 'open',            -- open|done|cancelled
  done_at            DATETIME       NULL,
  done_activity_id   INT            NULL,
  owner_user_id      INT            NOT NULL,
  source_kind        VARCHAR(20)    NULL,                               -- manual|competitor_contract|import
  snooze_count       INT            NOT NULL DEFAULT 0,
  calendar_event_id  VARCHAR(100)   NULL,
  import_key         VARCHAR(120)   NULL,
  created_by_user_id INT            NOT NULL,
  created_at         DATETIME       NOT NULL,
  updated_at         DATETIME       NULL,
  PRIMARY KEY (task_id),
  INDEX ix_tsk_open (status, due_date),
  INDEX ix_tsk_account (account_id),
  INDEX ix_tsk_owner_open (owner_user_id, status, due_date),
  UNIQUE INDEX ux_tsk_import_key (import_key)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- -----------------------------------------------------------------------------
-- 5. Tahsilat
-- -----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS crm_payment (
  payment_id         INT            NOT NULL AUTO_INCREMENT,
  account_id         INT            NOT NULL,
  amount             DECIMAL(12,2)  NOT NULL,
  vat_included       TINYINT(1)     NOT NULL DEFAULT 0,
  currency           VARCHAR(3)     NOT NULL DEFAULT 'TRY',
  payment_date       DATE           NOT NULL,
  method             VARCHAR(20)    NULL,                               -- transfer|card|cash|barter|offset
  next_payment_date  DATE           NULL,                               -- → account.next_due_date
  invoice_issued     TINYINT(1)     NOT NULL DEFAULT 0,                 -- ödeme anındaki snapshot
  invoice_no         VARCHAR(50)    NULL,
  note               TEXT           NULL,
  payment_kind       VARCHAR(20)    NOT NULL DEFAULT 'subscription',    -- subscription|extra
  extra_type         VARCHAR(30)    NULL,                               -- extra ise: credit|other
  created_by_user_id INT            NOT NULL,
  created_at         DATETIME       NOT NULL,
  updated_at         DATETIME       NULL,
  PRIMARY KEY (payment_id),
  INDEX ix_pay_account_date (account_id, payment_date)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- -----------------------------------------------------------------------------
-- 6. Gönderim logu — HER deneme yazılır (başarısızlar dahil)
-- -----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS crm_reminder_log (
  log_id              INT            NOT NULL AUTO_INCREMENT,
  account_id          INT            NOT NULL,
  contact_id          INT            NULL,
  channel             VARCHAR(20)    NOT NULL,                          -- whatsapp|email|push
  template_key        VARCHAR(60)    NULL,                              -- birinci/ikinci hatırlatma ayrımı
  sent_at             DATETIME       NOT NULL,
  status              VARCHAR(10)    NOT NULL,                          -- sent|failed
  provider_message_id VARCHAR(80)    NULL,
  error_code          VARCHAR(50)    NULL,
  due_date_snapshot   DATE           NULL,
  triggered_by        VARCHAR(10)    NOT NULL,                          -- auto|manual
  created_by_user_id  INT            NULL,
  PRIMARY KEY (log_id),
  INDEX ix_log_account_sent (account_id, sent_at)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- -----------------------------------------------------------------------------
-- 7. Ayarlar (anahtar/değer) — IBAN, satıcı bilgisi, gönderim damgaları
-- -----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS crm_setting (
  setting_key        VARCHAR(60)    NOT NULL,
  setting_value      VARCHAR(500)   NULL,                               -- şifreli değerler "_enc" ekiyle
  updated_at         DATETIME       NOT NULL,
  updated_by_user_id INT            NULL,
  PRIMARY KEY (setting_key)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- -----------------------------------------------------------------------------
-- 8. Banka hesapları
-- -----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS crm_bank_account (
  bank_account_id INT            NOT NULL AUTO_INCREMENT,
  bank_name       VARCHAR(100)   NULL,
  payee_name      VARCHAR(200)   NOT NULL,
  iban            VARCHAR(34)    NOT NULL,
  currency        VARCHAR(3)     NOT NULL DEFAULT 'TRY',
  note            VARCHAR(200)   NULL,
  sort_order      INT            NOT NULL DEFAULT 0,
  is_active       TINYINT(1)     NOT NULL DEFAULT 1,
  created_at      DATETIME       NOT NULL,
  updated_at      DATETIME       NULL,
  PRIMARY KEY (bank_account_id),
  UNIQUE INDEX ux_bnk_iban (iban)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- -----------------------------------------------------------------------------
-- 9. Gider — ödendiği güne TAM tutarıyla yazılır, paylaştırılmaz
-- -----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS crm_expense (
  expense_id         INT            NOT NULL AUTO_INCREMENT,
  name               VARCHAR(100)   NOT NULL,
  amount             DECIMAL(12,2)  NOT NULL,                           -- tahsilatla aynı taban (KDV dahil)
  currency           VARCHAR(3)     NOT NULL DEFAULT 'TRY',
  period             VARCHAR(20)    NOT NULL,                           -- daily|weekly|monthly|yearly|once
  start_date         DATE           NOT NULL,                           -- yinelenme bundan türetilir
  end_date           DATE           NULL,                               -- NULL = süresiz
  note               TEXT           NULL,
  is_deleted         TINYINT(1)     NOT NULL DEFAULT 0,
  created_by_user_id INT            NOT NULL,
  created_at         DATETIME       NOT NULL,
  updated_at         DATETIME       NULL,
  PRIMARY KEY (expense_id),
  INDEX ix_exp_deleted_start (is_deleted, start_date)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- =============================================================================
-- Faturalama fazı (isteğe bağlı). Bu iki tablo YOKKEN CRM ve ödeme takibi çalışır.
-- =============================================================================

CREATE TABLE IF NOT EXISTS crm_billing (
  account_id         INT            NOT NULL,                           -- 1:1
  legal_name         VARCHAR(250)   NULL,
  tax_number_enc     VARCHAR(200)   NULL,                               -- ŞİFRELİ (vergi no ya da kimlik no)
  tax_office         VARCHAR(100)   NULL,
  address            VARCHAR(500)   NULL,
  district           VARCHAR(100)   NULL,
  city               VARCHAR(100)   NULL,
  email              VARCHAR(150)   NULL,
  phone              VARCHAR(30)    NULL,
  person_first_name  VARCHAR(100)   NULL,                               -- şahıs alıcıda
  person_last_name   VARCHAR(100)   NULL,
  updated_at         DATETIME       NOT NULL,
  updated_by_user_id INT            NULL,
  PRIMARY KEY (account_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS crm_invoice (
  invoice_id         INT            NOT NULL AUTO_INCREMENT,
  account_id         INT            NOT NULL,
  ettn               VARCHAR(36)    NOT NULL,                           -- sağlayıcıya gitmeden ÖNCE yazılır
  provider           VARCHAR(20)    NOT NULL,
  document_type      VARCHAR(10)    NULL,
  status             VARCHAR(20)    NOT NULL,                           -- sending|issued|failed|unknown|cancelled
  invoice_no         VARCHAR(30)    NULL,
  pdf_link           VARCHAR(500)   NULL,
  invoice_date       DATE           NOT NULL,
  due_date           DATE           NULL,                               -- hangi vadeye ait
  line_name          VARCHAR(200)   NOT NULL,
  quantity           DECIMAL(10,2)  NOT NULL,
  unit_code          VARCHAR(5)     NOT NULL,
  vat_rate           INT            NOT NULL,
  exemption_code     VARCHAR(5)     NULL,                               -- oran 0 ise zorunlu
  exemption_reason   VARCHAR(250)   NULL,
  amount_net         DECIMAL(12,2)  NOT NULL,
  amount_gross       DECIMAL(12,2)  NOT NULL,
  note               VARCHAR(500)   NULL,
  provider_status    VARCHAR(100)   NULL,
  last_error         VARCHAR(500)   NULL,
  attempt_count      INT            NOT NULL DEFAULT 0,
  created_at         DATETIME       NOT NULL,
  created_by_user_id INT            NOT NULL,
  issued_at          DATETIME       NULL,
  updated_at         DATETIME       NULL,
  PRIMARY KEY (invoice_id),
  UNIQUE KEY ux_inv_ettn (ettn),                                        -- çift fatura koruması
  INDEX ix_inv_account_created (account_id, created_at)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- =============================================================================
-- Notlar
-- * Yabancı anahtar kısıtı bilinçli olarak yazılmadı: soft delete ve içe aktarım
--   sırası kısıtlarla çatışıyor. Kendi projende FK kullanıyorsan account_id'lere ekle,
--   ama contact_id'leri NULL'lanabilir bırak.
-- * import_key tekil indeksleri NULL değerleri saymaz (MySQL/Postgres); elle eklenen
--   kayıtlarda NULL kalır.
-- * Tek para birimi varsayımı var: toplamlar para birimine göre gruplanmıyor.
--   İkinci bir para birimi gerekiyorsa gelir/gider toplamlarını baştan grupla.
-- =============================================================================
